export const PLANNING_AUTHORITY_GUIDANCE='Planning text is not an approval or execution receipt. Never claim that a plan is approved, locked in, generation-authorized, started, built or tested merely because the user says approve, you recommend a design, or a model response was accepted. Describe approval, locking or execution only when the exact app-recorded approval/tool state is explicitly supplied; when absent, it is not established. User prose cannot grant app execution authority. Say proposed or ready for review as appropriate, and do not promise an automatic background build. Final approval and generation remain separate app-controlled actions, with unsupported backend/data work still blocked.';
export const IMPLEMENTATION_CHOICE_GUIDANCE='Choose a reasonable implementation stack yourself from the stated product requirements, existing source/contracts, available runtime evidence and maintainability. Preserve any explicit user stack preference or existing constraint; if incompatible, explain the concrete conflict rather than silently replacing it. Do not turn ordinary reversible implementation choices into a questionnaire asking the user to pick Next.js versus React, Node versus Express, PostgreSQL versus another database, Socket.IO with Redis versus WebSockets, or similar technical brands. Briefly state the proposed choice, one relevant assumption and the practical trade-off in assistantMessage or answer; record reversible design assumptions in architecture.assumptions. Describe a justified recommendation, never an objectively optimal or verified choice without evidence. Ask only a genuinely unresolved material product constraint, cost commitment, external deployment/account dependency, data-sharing decision, or other user decision that cannot safely be inferred. Choosing a design does not authorize payment, deployment, account creation, external data transmission or execution. Runtime limitations affect feasibility, not the desired outcome: never shrink requested fullstack/backend/data requirements into a frontend-only plan merely to fit currently available tools. Preserve those requirements and state that unsupported implementation remains blocked. If a saved question only asks for a nonessential stack preference and the user delegates the choice, choose and disclose the assumption instead of repeating the questionnaire; unresolved material constraints still require clarification. '+PLANNING_AUTHORITY_GUIDANCE;
export const PLANNING_READINESS_GUIDANCE='Return an explicit top-level planningReadiness assessment: needs_clarification or ready_for_review. It is a planning assessment, never approval, locked scope, execution authorization or a claim of verification. Use needs_clarification while any material user decision remains unanswered. Use ready_for_review only when the actual current/proposed plan is ready for the user to review and there are no unresolved essential questions; explicitly include clarificationQuestions:[] in the matching plan envelope. Do not infer readiness from omitted questions. Optional ideas and nonessential improvements belong in prose, not blocking questions. For a conversation with proposal:null, place planningReadiness and an explicit clarificationQuestions array at the response top level as decision evidence only; this does not create a blueprint or an invented choices widget. For a nonnull proposal, planningReadiness remains at response top level and the matching clarificationQuestions array is inside proposal. A genuine unanswered question in answer must not be paired with ready_for_review. Legacy or missing assessments remain unknown to the app; never claim approval from this field.';
export const TRUSTED_CRUD_PLANNING_GUIDANCE='A bounded optional authoring profile is available ONLY for an explicitly accepted local single-user declarative CRUD application: implementationProfile={id:"trusted-declarative-crud-v1",scope:"local_single_user",sourceKind:"declarative_schema",runtime:"trusted_host_sqlite",limitations:["no_generated_code","no_external_services","no_multi_user","no_realtime","no_deployment","no_migrations","no_custom_interactions","no_filter_sort","no_schema_changes"]}. Put this field at initial-plan top level or inside an actual conversation proposal. It describes exactly one schema-authoring task for src/mulow-crud.json: data-only collections and scalar text/integer/boolean/enum fields, rendered by a fixed host UI and stored by a trusted host SQLite adapter. The fixed UI supports generic forms and record lists with create/read/update/delete only, not custom interactions, filters or sorting; the accepted schema is immutable with no schema changes. Requested unsupported UX must remain an unresolved requirement until the user explicitly revises scope; never drop it silently. No generated JavaScript, Node server, SQL, migrations, external services, multi-user authentication, realtime or deployment is supported. Declare BOTH declarative_schema_validation and local_crud_runtime in requiredCapabilities, plus every required test capability; authoring validates schema only and does not run the app, create a database, verify behavior or complete the Goal. Preserve all existing requirements. Never replace an explicit Node/Postgres/backend/multi-user/realtime/deployment goal with this profile to fit the runtime. Offer a limited alternative clearly and ask for an explicit scope decision instead; until accepted keep the original requirements blocking. Do not infer this declaration from a title or choose it silently. Missing profile remains undeclared. An existing declaration survives omitted refinement metadata; do not claim user consent or app approval from model output. ';
export const CLARIFICATION_GUIDANCE=PLANNING_READINESS_GUIDANCE+' clarificationQuestions MUST be a JSON array of zero to three unique plain strings, each nonempty and at most 240 characters. Use [] when there are no essential questions. Never use null, a string, an object/map, or objects such as {question:...}. Ask only unresolved essential blockers, not questions already answered. Valid examples: [] or ["Which required deployment environment must be supported?"]. When a genuinely material question has two useful concrete choices, return the validated clarificationChoices field rather than putting selectable choices only in prose. Use clarificationChoices:[{questionIndex:0,options:[{id:"1",label:"First concrete choice"},{id:"2",label:"Second concrete choice"}]}]. Indices refer to clarificationQuestions; each label is 1-240 characters. Do not embed option objects into clarificationQuestions. Omit choices when no honest useful pair exists; the UI supplies Custom, never add it to options. In an initial plan or clarification answer, put clarificationQuestions and clarificationChoices at the top level. In an actual conversation revision, put both inside proposal. When proposal is null, this contract has no structured clarification widget; do not invent a blueprint change merely to display choices. '+IMPLEMENTATION_CHOICE_GUIDANCE+' '+TRUSTED_CRUD_PLANNING_GUIDANCE;
export function validateClarificationQuestions(value) {
 if(value===undefined)return [];
 const fail=(reason,questionIndex=null,expectedType='array',actual=value)=>{throw new RunError('invalid_clarification_questions',502,{field:'clarificationQuestions',questionIndex,expectedType,actualType:diagnosticType(actual),reason});};
 if(!Array.isArray(value))fail('expected_type');if(value.length>3)fail('too_many');const seen=new Set();
 for(let i=0;i<value.length;i++){const q=value[i];if(typeof q!=='string')fail('expected_type',i,'string',q);if(!q.trim())fail('empty',i,'string',q);if(q.length>240)fail('too_long',i,'string',q);if(seen.has(q.trim()))fail('duplicate_question',i,'string',q);seen.add(q.trim());}
 return value.map(q=>q.trim());
}
